  ok(vol && Number(vol[3]) === Number(f1(Number(vol[1]) * Number(vol[2]))), `gripper: expected/grip-finger.txt mass ${vol && vol[3]} != volume × density`);
  const [V, rho, mass] = vol ? [vol[1], vol[2], f1(Number(vol[1]) * Number(vol[2]))] : ["?", "?", "?"];
