{
  // Month 6 content gaps (m6-report.md Section B): every newly stated number is recomputed or pinned here.
  // act-diffusion: ACT temporal ensembling w_i=exp(−m·i) (Zhao et al. Alg. 2); diffusion perfect-denoiser Gaussian weights.
  // behaviour-cloning: squared-loss mean ≡ 1-NN when locally unimodal; covariate-shift recurrence p_{t+1}=p_t+a_t+ε_t.
  // policy-evaluation: Binomial(10,0.65) SD; mean failure step 41.3 vs demo length 38–39 / 5 cm goal (row "trials needed" already on main).
  // specialisation-portfolio: O(N) vs O(log N), 10^6/3061≈327×; start-list sized with trials_needed (82 / 199).
  // vla-models: 256 = Llama least-used token overlay (OpenVLA §3.2); DCT rounding threshold 1/(2·scale); third-part claim attributed.
  const rd6 = (p) => readFileSync(join(root, p), "utf8");
  const bc = rd6("examples/month-6/behaviour-cloning/bc_reach.py");
  const multi = rd6("examples/month-6/act-diffusion/multimodal.py");
  const tokens = rd6("examples/month-6/vla-models/action_tokens.py");
  const num6 = (text, re, what) => { const m = text.match(re); ok(m, `m6: ${what} not found`); return m ? Number(m[1]) : NaN; };
  const goalR = 0.05;
  ok(/math\.hypot\(p\[0\] - GOAL\[0\], p\[1\] - GOAL\[1\]\) < 0\.05/.test(bc), `m6 bc: success radius must be 0.05 m`);
  const noise = num6(bc, /HALF_WIDTH, STEP, NOISE, MAX_STEPS = [\d.]+, [\d.]+, ([\d.]+)/, "bc NOISE");
  const maxSteps = num6(bc, /HALF_WIDTH, STEP, NOISE, MAX_STEPS = [\d.]+, [\d.]+, [\d.]+, (\d+)/, "bc MAX_STEPS");
  ok(noise === 0.01 && maxSteps === 80, `m6 bc: NOISE=${noise} MAX_STEPS=${maxSteps}`);
  // episode length 38–39 and 3061 frames are printed by bc_reach.py (seeded); pin the lesson figures.
  const frames80 = 3061;
  const demoLo = 38, demoHi = 39;
  const factor = 1e6 / frames80;
  ok(Math.abs(factor - 326.6906239790918) < 1e-9 && Math.round(factor) === 327,
    `m6 portfolio: 1e6/${frames80} must round to 327 (got ${factor})`);
  const pRate = 0.65, nSess = 10;
  const binomSd = Math.sqrt(nSess * pRate * (1 - pRate));
  ok(Math.abs(binomSd - 1.5083103128998356) < 1e-12 && Math.round(binomSd * 100) / 100 === 1.51,
    `m6 eval: Binomial(10,0.65) SD=${binomSd} must be ≈1.51`);
  // trials_needed(0.6,0.8)=82, (0.8,0.9)=199 — same formula as eval_report.py (already worked in lesson; re-pin for portfolio cite).
  const z95 = 1.959963984540054, z80 = 0.8416212335729143;
  const tn = (p1, p2) => {
    const pb = (p1 + p2) / 2;
    const num = z95 * Math.sqrt(2 * pb * (1 - pb)) + z80 * Math.sqrt(p1 * (1 - p1) + p2 * (1 - p2));
    return Math.ceil((num * num) / ((p1 - p2) * (p1 - p2)));
  };
  ok(tn(0.6, 0.8) === 82 && tn(0.8, 0.9) === 199, `m6 portfolio: trials_needed 60/80→${tn(0.6,0.8)} 80/90→${tn(0.8,0.9)}`);
  const bins = num6(tokens, /HZ, CHUNK, JOINTS, BINS = \d+, \d+, \d+, (\d+)/, "vla BINS");
  ok(bins === 256, `m6 vla: BINS must be 256 (got ${bins})`);
  ok(/round\(c \* scale\)/.test(tokens), `m6 vla: DCT path must round(c * scale)`);
  // perfect-denoiser weight in multimodal.py: exp(−‖x−√ᾱ d‖² / (2(1−ᾱ)))
  ok(/math\.exp\(/.test(multi) && /1\s*-\s*abar/.test(multi), `m6 act-diffusion: multimodal.py must compute Gaussian denoiser weights`);
  const phrases = {
    en: {
      "act-diffusion": [
        "w_i = exp(−m · i)",
        "w_d ∝ exp(−‖x_s − √ᾱ_s d‖² / (2(1 − ᾱ_s)))",
        "Algorithm 2",
        "effective horizon shrinks by k",
      ],
      "behaviour-cloning": [
        "`p_{t+1} = p_t + a_t + ε_t`",
        "locally unimodal",
        "conditional mean",
      ],
      "policy-evaluation": [
        "Binomial(10, 0.65)",
        "√(10 × 0.65 × 0.35) ≈ 1.51",
        "38 to 39 frames",
        "5 cm success radius",
        "mean step 41.3",
      ],
      "specialisation-portfolio": [
        "10⁶ / 3061 ≈ 327",
        "O(N)",
        "O(log N)",
        "about 82 trials",
        "about 199",
      ],
      "vla-models": [
        "vocabulary budget",
        "1/(2 · scale)",
        "arXiv:2406.09246",
        "arXiv:2501.09747",
        "attributed claim",
      ],
    },
    zh: {
      "act-diffusion": [
        "w_i = exp(−m · i)",
        "w_d ∝ exp(−‖x_s − √ᾱ_s d‖² / (2(1 − ᾱ_s)))",
        "算法 2",
        "有效时域缩短为原来的 1/k",
      ],
      "behaviour-cloning": [
        "`p_{t+1} = p_t + a_t + ε_t`",
        "单峰",
        "条件均值",
      ],
      "policy-evaluation": [
        "Binomial(10, 0.65)",
        "√(10 × 0.65 × 0.35) ≈ 1.51",
        "38 到 39 帧",
        "5 cm 成功半径",
        "平均第 41.3 步",
      ],
      "specialisation-portfolio": [
        "10⁶ / 3061 ≈ 327",
        "O(N)",
        "O(log N)",
        "大约需要 82 次",
        "大约需要 199 次",
      ],
      "vla-models": [
        "词表预算",
        "1/(2 · scale)",
        "arXiv:2406.09246",
        "arXiv:2501.09747",
        "带出处的表述",
      ],
    },
  };
  for (const lang of ["en", "zh"]) {
    for (const [slug, qs] of Object.entries(phrases[lang])) {
      const text = rd6(`src/content/m6/${slug}/${lang}.mdx`);
      for (const q of qs) ok(text.includes(q), `m6 ${slug} ${lang}: expected ${JSON.stringify(q)}`);
    }
  }
  console.log(`calc  m6 gaps: binom SD=${binomSd.toFixed(2)}; 1e6/${frames80}≈${Math.round(factor)}; trials_needed 82/199; goal ${goalR} m; demo ${demoLo}–${demoHi} frames; BINS=${bins}; DCT round thresh 1/(2·scale); ACT w_i / diffusion w_d bound; attributed OpenVLA/RT-2; bound in en/zh`);
}



const specs = [];
for (const f of readdirSync(specDir).filter((f) => f.endsWith(".ts"))) {
  const mod = await import(dataUrl(transpile(inlineJson(readFileSync(join(specDir, f), "utf8")))));
  for (const [name, v] of Object.entries(mod)) if (v && typeof v === "object" && v.kind) specs.push({ file: f, name, spec: v });
}
const index = readFileSync(join(root, "src/lib/diagrams/index.ts"), "utf8");
const ids = new Set();

for (const { file, name, spec } of specs) {
  const tag = `${spec.id} (${file}:${name})`;
  ok(!ids.has(spec.id), `${tag}: duplicate id`);
  ids.add(spec.id);
  ok(new RegExp(`\\[${name}\\.id\\]: ${name}`).test(index), `${tag}: not registered in src/lib/diagrams/index.ts`);
  checkText(`${tag} title`, spec.title);
  checkText(`${tag} caption`, spec.caption);
  for (const src of spec.sources) ok(existsSync(join(root, src)), `${tag}: source ${src} does not exist`);
  if (spec.kind === "circuit") checkCircuit(spec, tag);
  else if (spec.kind === "timing") checkTiming(spec, tag);
  else if (spec.kind === "bytes") checkBytes(spec, tag);
  else if (spec.kind === "poseGraph") checkPoseGraph(spec, tag);
  else if (spec.kind === "geo") checkGeo(spec, tag);
  else {
    const nodeIds = new Set(spec.nodes.map((n) => n.id));
    const edgeIds = new Set(spec.edges.map((e) => e.id));
    for (const n of spec.nodes) { checkText(`${tag} node ${n.id}`, n.label, n); checkText(`${tag} node ${n.id} sub`, n.sub, { mono: n.subMono }); }
    for (const e of spec.edges) checkText(`${tag} edge ${e.id}`, e.label, e);
    for (const [k, s] of (spec.steps ?? []).entries()) {
      checkText(`${tag} step ${k + 1}`, s.label);
      for (const h of s.highlight) ok(nodeIds.has(h) || edgeIds.has(h), `${tag} step ${k + 1}: unknown id "${h}"`);
    }
    if (spec.kind === "stateMachine") ok(nodeIds.has(spec.initial), `${tag}: initial state "${spec.initial}" missing`);
    checkScript(spec, tag);
    checkBindings(spec, tag, nodeIds, edgeIds);
    checkFlows(spec, tag);

    for (const which of ["wide", "narrow"]) {
      const L = spec.layouts[which];
      const lt = `${tag} ${which}`;
      if (which === "narrow") ok(L.w <= NARROW_MAX, `${lt}: width ${L.w} > ${NARROW_MAX} (text would render below ${MIN_PX} px on a 390 px phone)`);
      else ok(L.w <= WIDE_MAX, `${lt}: width ${L.w} > ${WIDE_MAX} (text would render below ${MIN_PX} px in the ${WIDE_BOX_PX} px box)`);
      const inside = (x, y, what) => ok(x >= 0 && y >= 0 && x <= L.w && y <= L.h, `${lt}: ${what} at (${x}, ${y}) is outside ${L.w}x${L.h}`);
      for (const n of spec.nodes) {
        const r = L.nodes[n.id];
        ok(r, `${lt}: node ${n.id} has no position`);
        if (!r) continue;
        const [x, y, w, h] = r;
        inside(x, y, `node ${n.id}`); inside(x + w, y + h, `node ${n.id}`);
        const shape = n.shape ?? (spec.kind === "stateMachine" ? "state" : "box");
        const room = shape === "state" ? w - h / 2 : shape === "text" ? w + 4 : w - 8;
        for (const t of variants(n.label)) ok(textWidth(t, FONT) <= room, `${lt}: node ${n.id} label "${t}" (${textWidth(t, FONT).toFixed(0)}) wider than ${room}`);
        for (const t of variants(n.sub)) {
          for (const line of lines(t)) ok(textWidth(line, SUB) <= room, `${lt}: node ${n.id} sub "${line}" (${textWidth(line, SUB).toFixed(0)}) wider than ${room}`);
          // same vertical placement as BlockDiagram.tsx: label baseline, then sub lines below it
          if (shape === "box" || shape === "state" || shape === "file") {
            const extra = (lines(t).length - 1) * (SUB + 2.5);
            const ly = y + h / 2 - 2 - extra / 2;
            const lastBase = ly + SUB + 3 + extra;
            ok(ly - FONT * 0.8 >= y && lastBase + 3 <= y + h, `${lt}: node ${n.id} label + ${lines(t).length} sub line(s) do not fit height ${h}`);
          }
        }
      }
      for (const e of spec.edges) {
        const g = L.edges[e.id];
        ok(g, `${lt}: edge ${e.id} has no geometry`);
        if (!g) continue;
        for (const [x, y] of g.pts) inside(x, y, `edge ${e.id} point`);
        if (e.label) {
          ok(g.label, `${lt}: edge ${e.id} label has no position`);
          if (!g.label) continue;
          for (const t of variants(e.label)) {
            lines(t).forEach((line, k) => {
              const w = textWidth(line, SUB);
              const a = g.anchor ?? "middle";
              const x0 = a === "start" ? g.label[0] : a === "end" ? g.label[0] - w : g.label[0] - w / 2;
              const yb = g.label[1] + k * (SUB + 2.5);
              inside(Math.floor(x0), Math.floor(yb - SUB), `edge ${e.id} label "${line}"`);
              inside(Math.ceil(x0 + w), Math.ceil(yb + 3), `edge ${e.id} label "${line}"`);
            });
          }
        }
      }
    }
  }

  for (const fact of spec.facts) {
    const p = join(root, fact.file);
    if (!existsSync(p)) { fail(`${tag}: fact file ${fact.file} missing`); continue; }
    const hit = new RegExp(fact.pattern, "m").test(readFileSync(p, "utf8"));
    ok(hit, `${tag}: fact not found in ${fact.file}: /${fact.pattern}/ (${fact.note})`);
    if (hit) console.log(`same  ${spec.id}: ${fact.note}  [${fact.file}]`);
  }
}

// Lessons: every <Diagram id> exists; zh and en use the same ids in the same order.
const content = join(root, "src/content");
for (const m of readdirSync(content)) {
  for (const lesson of readdirSync(join(content, m))) {
    const get = (loc) => {
      const p = join(content, m, lesson, `${loc}.mdx`);
      return existsSync(p) ? [...readFileSync(p, "utf8").matchAll(/<Diagram id="([^"]+)" \/>/g)].map((x) => x[1]) : [];
    };
    const en = get("en"), zh = get("zh");
    ok(JSON.stringify(en) === JSON.stringify(zh), `${m}/${lesson}: zh diagrams ${JSON.stringify(zh)} differ from en ${JSON.stringify(en)}`);
    for (const id of en) ok(ids.has(id), `${m}/${lesson}: <Diagram id="${id}" /> is not registered`);
  }
}

// ---------- minimum text size outside the registry (12 px rule, docs/notes/diagrams.md) ----------
// Static guards; the rendered check is tools/check_text_size.mjs (Playwright, run by hand).
{
  const walk = (dir) => readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)]));
  const files = ["src/components", "src/app", "src/content"].flatMap((d) => walk(join(root, d))).filter((f) => /\.(tsx|mdx)$/.test(f));
  const rel = (f) => f.slice(root.length + 1);
  for (const f of files) {
    const src = readFileSync(f, "utf8");
    // Tailwind arbitrary sizes below 12 px (text-[11px]) in HTML or SVG
    for (const m of src.matchAll(/text-\[(\d+(?:\.\d+)?)px\]/g)) ok(Number(m[1]) >= MIN_PX, `${rel(f)}: ${m[0]} is below ${MIN_PX} px; use text-xs or larger`);
    // literal SVG font sizes (attribute or style object) below 12 units render below 12 px unless the SVG is scaled up
    // forms: fontSize="10" / {10} / {"10px"} and style objects { fontSize: 10 } / "10px" / '10' / `10px`; a value that
    // continues after the number (DG_FONT, 10 * k, `${n}px`) is not a literal and is skipped
    const FS = /fontSize\s*[=:]\s*\{?\s*(?:(["'`])(\d+(?:\.\d+)?)(?:px)?\1|(\d+(?:\.\d+)?)(?:px)?\s*(?=[},]|$))/gm;
    for (const m of src.matchAll(FS)) {
      const v = m[2] ?? m[3];
      ok(Number(v) >= MIN_PX, `${rel(f)}: fontSize ${v} is below ${MIN_PX} units`);
    }
  }

  // <Chart>: the viewBox follows the box width below W_MAX, so FONT units render at FONT px on a phone
  const chartSrc = readFileSync(join(root, "src/components/widgets/Chart.tsx"), "utf8");
  const chartFont = Number(chartSrc.match(/const FONT = ([\d.]+)/)?.[1]);
  ok(chartFont >= MIN_PX, `Chart.tsx: FONT ${chartFont} < ${MIN_PX}`);
  ok(/useBoxWidth/.test(chartSrc) && chartSrc.includes("viewBox={`0 0 ${W} ${H}`}"), "Chart.tsx: the viewBox must follow the measured box width (useBoxWidth)");

  // <QuadratureTiming>: 8 columns of QUAD_COL units in TimingSvg on one line; smallest text 14 units
  const quadSrc = readFileSync(join(root, "src/components/diagrams/Quadrature.tsx"), "utf8");
  const quadCol = Number(quadSrc.match(/export const QUAD_COL = ([\d.]+)/)[1]);
  const quadW = T.LEFT + 8 * quadCol + 8;
  const quadPx = (14 * PHONE_BOX) / quadW;
  ok(quadPx >= MIN_PX, `Quadrature.tsx: the ${quadW}-unit diagram renders 14-unit text at ${quadPx.toFixed(1)} px on a 390 px phone (< ${MIN_PX})`);
  const centre = T.LEFT + 4 * quadCol;
  let quads = 0;
  for (const f of files.filter((x) => x.endsWith(".mdx"))) {
    for (const m of readFileSync(f, "utf8").matchAll(/<QuadratureTiming[^>]*axisLabel="([^"]+)"[^>]*countLabel="([^"]+)"/g)) {
      quads++;
      ok(textWidth(m[1], 14) / 2 <= Math.min(centre, quadW - centre), `${rel(f)}: QuadratureTiming axisLabel "${m[1]}" wider than the diagram`);
      ok(textWidth(m[2], 15) <= T.LEFT - 12, `${rel(f)}: QuadratureTiming countLabel "${m[2]}" wider than the label column`);
    }
  }
  ok(quads > 0, "no <QuadratureTiming> found in the lessons (the size check above would test nothing)");
}

// House style, site-wide: a space before the percent sign ("15 %"), never "15%", "15％" or "15 ％". Every lesson
// (en and zh) and every text file under src/lib (glossary, curriculum, resources, ...) is read; fenced code blocks
// (scripts and their real output) and link targets ("%20" in a URL) are exempt. Reader-visible UI text is read too:
// JSX text and string/template literals in src/components and src/app, and the i18n strings in messages/*.json, where
// an interpolation glued to the sign ("{percent}%", "${x}%") also counts. CSS values are exempt there: style={{ … }},
// className / width / height attributes and rootMargin, and so are // and /* */ comments.
{
  const walk = (d) => readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(join(d, e.name)) : [join(d, e.name)]));
  const pctFiles = [...walk(join(root, "src/content")).filter((f) => f.endsWith(".mdx")), ...walk(join(root, "src/lib")).filter((f) => /\.tsx?$/.test(f))];
  const bad = [];
  for (const f of pctFiles) {
    const text = readFileSync(f, "utf8").replace(/^```[^\n]*\n[\s\S]*?^```/gm, (m) => m.replace(/[^\n]/g, "")).replace(/\]\([^)\s]*\)/g, "]");
    text.split("\n").forEach((l, i) => { for (const m of l.matchAll(/\d%|\d\s*％/g)) bad.push(`${f.slice(root.length + 1)}:${i + 1} "${m[0]}"`); });
  }
  const blank = (m) => m.replace(/[^\n]/g, "");
  const dropStyle = (s) => {
    let out = "", i = 0;
    for (let k; (k = s.indexOf("style={", i)) >= 0; ) {
      let d = 0, j = k + 6;
      do { if (s[j] === "{") d++; else if (s[j] === "}") d--; j++; } while (d > 0 && j < s.length);
      out += s.slice(i, k) + blank(s.slice(k, j)); i = j;
    }
    return out + s.slice(i);
  };
  const uiFiles = [...walk(join(root, "src/components")), ...walk(join(root, "src/app"))].filter((f) => /\.tsx?$/.test(f));
  const msgFiles = ["en", "zh"].map((l) => join(root, `messages/${l}.json`));
  for (const f of [...uiFiles, ...msgFiles]) {
    let text = readFileSync(f, "utf8");
    if (!f.endsWith(".json"))
      text = dropStyle(text.replace(/\/\*[\s\S]*?\*\//g, blank)).replace(/(^|[^:"'`\w])\/\/.*$/gm, "$1")
        .replace(/\b(?:className|width|height)=(?:"[^"]*"|\{[^{}\n]*\})/g, "").replace(/\brootMargin:\s*"[^"]*"/g, "");
    text.split("\n").forEach((l, i) => { for (const m of l.matchAll(/[\d}]%|[\d}]\s*％/g)) bad.push(`${f.slice(root.length + 1)}:${i + 1} "${m[0]}"`); });
  }
  ok(pctFiles.length > 100 && uiFiles.length > 20 && uiFiles.some((f) => f.endsWith("ProgressBar.tsx")) && bad.length === 0,
    `write percentages with a space ("15 %"), not ${bad.slice(0, 20).join(", ")}${bad.length > 20 ? ` and ${bad.length - 20} more` : ""}`);
  console.log(`style percent: ${pctFiles.length} files (lessons + src/lib), ${uiFiles.length} UI files (src/components + src/app) and ${msgFiles.length} message files, ${bad.length} without the space`);
}

console.log(`\n${specs.length} diagrams, ${checks} checks, ${failed} failed`);
process.exit(failed ? 1 : 0);
